<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Color Generator Online','description'=>'Generate random HEX colors instantly and copy the value.','url'=>'https://smarttoolz.in/tools/color-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">COLOR GENERATOR</span><h1>Random Color Generator</h1><p>Generate random colors and copy their HEX codes.</p></section><section class="tool-workspace"><div class="tool-panel" style="text-align:center"><div id="c" style="height:220px;border-radius:18px;display:grid;place-items:center;font-size:25px;font-weight:900;text-shadow:0 1px 4px #000;color:#fff">#000000</div><button id="go" class="tool-btn" style="margin-top:15px">Generate Color</button><button id="copy" class="tool-btn" style="margin-top:10px">Copy HEX</button></div></section></main><script>(()=>{const c=document.getElementById('c');function gen(){let x='#'+(Math.random()*16777215|0).toString(16).padStart(6,'0');c.style.background=x;c.textContent=x.toUpperCase()}document.getElementById('go').onclick=gen;document.getElementById('copy').onclick=()=>navigator.clipboard.writeText(c.textContent);gen()})();</script><?php smarttoolz_tool_page_end(); ?>